import pg from './node_modules/pg/lib/index.js';
const start=performance.now(),startedAt=new Date().toISOString();
const expected=JSON.parse(process.env.K01_EXPECTED_IDENTITY);
const pool=new pg.Pool({connectionString:process.env.FLOW_K01_QUERY_ADMIN_URL,max:1,connectionTimeoutMillis:1000,statement_timeout:1500,lock_timeout:500,query_timeout:1800,application_name:'k01-query-recovery-readonly'});
let rows=null,error=null,closed=false;pool.on('error',e=>{error={code:e.code??'POOL_ERROR'};});
try{rows=(await pool.query("SELECT d.datname AS name,d.oid::text AS oid,pg_get_userbyid(d.datdba) AS owner,shobj_description(d.oid,'pg_database') AS marker,(SELECT count(*)::int FROM pg_stat_activity a WHERE a.datid=d.oid) AS connections FROM pg_database d WHERE d.datname=$1",[expected.database])).rows;}
catch(e){error={code:e.code??'QUERY_ERROR'};}
finally{await pool.end();closed=true;}
const row=rows?.[0],identityMatched=rows?.length===1&&row.name===expected.database&&row.oid===expected.identity.oid&&row.owner===expected.identity.owner&&row.marker===expected.identity.marker;
const passed=closed&&!error&&identityMatched&&row.connections===0;
console.log(JSON.stringify({startedAt,endedAt:new Date().toISOString(),elapsedMs:performance.now()-start,rows,identityMatched,closed,passed,error}));if(!passed)process.exitCode=1;
